package br.com.wagnertomaszewski.painelmandato;
import org.junit.Test;import static org.junit.Assert.*;
import java.io.IOException;import java.security.*;import javax.crypto.Cipher;import java.nio.charset.StandardCharsets;

public class CidadaoBiometriaTest {
    private static final String CHAVE="AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";
    private KeyPair par()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("RSA");g.initialize(2048);return g.generateKeyPair();}
    @Test public void protocoloIsoladoNaoProduzCredencial()throws Exception{assertThrows(IOException.class,()->CredencialCidadao.nova("2026-900000",null,1000));assertThrows(IOException.class,()->CredencialCidadao.nova("2026-900000","123456",1000));assertThrows(IOException.class,()->CredencialCidadao.nova("",CHAVE,1000));assertThrows(IOException.class,()->CredencialCidadao.nova("protocolo\nindevido",CHAVE,1000));}
    @Test public void credencialPersistidaSomenteCifradaERestauravelNoMesmoAparelho()throws Exception{CredencialCidadao c=CredencialCidadao.nova("2026-900000",CHAVE,1000);KeyPair p=par();byte[] b=EnvelopeSessao.selar(c.codificar(),p.getPublic());assertFalse(new String(b,StandardCharsets.ISO_8859_1).contains(CHAVE));CredencialCidadao d=CredencialCidadao.ler(EnvelopeSessao.abrir(EnvelopeSessao.ler(b),EnvelopeSessao.rsa(Cipher.DECRYPT_MODE,p.getPrivate())));assertEquals(c.protocolo,d.protocolo);assertEquals(c.chave,d.chave);}
    @Test public void copiaDoEnvelopeParaOutroAparelhoNaoDesbloqueia()throws Exception{KeyPair a=par(),b=par();byte[] e=EnvelopeSessao.selar(CredencialCidadao.nova("2026-900000",CHAVE,1000).codificar(),a.getPublic());assertThrows(GeneralSecurityException.class,()->EnvelopeSessao.abrir(EnvelopeSessao.ler(e),EnvelopeSessao.rsa(Cipher.DECRYPT_MODE,b.getPrivate())));}
    @Test public void expiracaoERecuoDoRelogioExigemValidacaoManual()throws Exception{CredencialCidadao c=CredencialCidadao.nova("2026-900000",CHAVE,1000);assertFalse(c.vigente(999));assertTrue(c.vigente(1000));assertTrue(c.vigente(c.expiraEm-1));assertFalse(c.vigente(c.expiraEm));assertFalse(c.vigente(c.expiraEm+1));}
    @Test public void formatoOuVersaoAdulteradosNaoSaoAceitos()throws Exception{byte[] e=CredencialCidadao.nova("2026-900000",CHAVE,1000).codificar();assertThrows(IOException.class,()->CredencialCidadao.ler(java.util.Arrays.copyOf(e,e.length-1)));assertThrows(IOException.class,()->CredencialCidadao.ler(java.util.Arrays.copyOf(e,e.length+1)));e[3]=2;assertThrows(IOException.class,()->CredencialCidadao.ler(e));}
    @Test public void ponteSoAceitaTelaPrivadaDaHomologacao(){assertTrue(CredencialCidadao.telaPermitida("https://mandato-neon-homologacao.onrender.com/hml/v2/recuperar#consulta"));for(String s:new String[]{"https://mandato-neon-homologacao.onrender.com/hml/","https://mandato-neon-homologacao.onrender.com/hml/painel/recuperacoes","https://mandato-neon-homologacao.onrender.com.evil/hml/v2/recuperar","https://mandato-neon-homologacao.onrender.com/hml/v2/recuperar?chave=indevida","https://wagnertomaszewski-boop.github.io/cartao-wagner-/v2/recuperar","http://mandato-neon-homologacao.onrender.com/hml/v2/recuperar"})assertFalse(CredencialCidadao.telaPermitida(s));}
    @Test public void cancelamentoENavegacaoInvalidamCallbackMesmoSeBiometriaTiverRespondido(){TentativasBiometricas t=new TentativasBiometricas();long inicio=t.iniciar();assertTrue(t.vigente(inicio));t.cancelar();assertFalse(t.vigente(inicio));long outra=t.iniciar();assertFalse(t.vigente(inicio));assertTrue(t.vigente(outra));t.fechar();assertFalse(t.vigente(outra));assertFalse(t.vigente(t.iniciar()));}
}
